import{_ as o}from"./chunks/maintenance-pwr.pc.en.DGccA8m3.js";import{_ as t,o as d,c as a,a5 as r}from"./chunks/framework.BjM_ivYE.js";const n="/RBQ/images/app/maintenance-vision.pc.en.png",i="/RBQ/images/app/maintenance-ini.pc.en.png",u=JSON.parse('{"title":"Maintenance","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/maintenance.md","filePath":"manual/gui/maintenance.md","lastUpdated":1790655143000}'),c={name:"manual/gui/maintenance.md"};function s(h,e,l,p,m,b){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h1><p>Open <code>Maintenance</code> with its tile on the hub; the tile works while the robot is connected. The sections are <code>Power / System</code>, <code>Vision</code>, <code>Config file</code>, and — on robots with an arm — <code>Arm</code>.</p><p><strong>This screen is <a href="/RBQ/manual/gui/developer-mode.html">developer mode</a> only, in its entirety.</strong> Without it the <code>Maintenance</code> tile is not shown on the hub and the route redirects to the control home. Everything here can cut the connection, drop the robot or change how its daemons start — read each warning before you press anything.</p><h2 id="power-system" tabindex="-1">Power / System <a class="header-anchor" href="#power-system" aria-label="Permalink to &quot;Power / System&quot;">​</a></h2><p><img src="'+o+'" alt="Power / System section"></p><p>This section exposes every PDU rail, including the ones deliberately kept out of Settings. Toggles show the real rail state from the robot; they are disabled until that state has been received.</p><p><strong>12 V toggles</strong> (one tap): <code>Speaker amp (12V)</code>, <code>LiDAR (12V)</code>, <code>CCTV (12V)</code>, <code>Thermal (12V)</code>, <code>IR LED (12V)</code>.</p><p><strong>Rails that break the link</strong> (two-step confirmation <code>Turn this off?</code> → <code>Turn off</code>; the dialog has a <code>Don&#39;t ask for a day</code> checkbox — once ticked, that rail switches without confirmation for 24 hours on this screen only; Robot settings → Power always confirms):</p><table tabindex="0"><thead><tr><th>Rail</th><th>Effect of switching off</th></tr></thead><tbody><tr><td><code>Cameras (5V)</code></td><td>Video stops.</td></tr><tr><td><code>Audio·USB hub (5V)</code></td><td>Audio devices disappear.</td></tr><tr><td><code>Vision PC (12V)</code></td><td>Cameras, audio and part of the telemetry on this screen stop.</td></tr><tr><td><code>Comm (12V)</code></td><td>The app&#39;s own connection to the robot is lost.</td></tr></tbody></table><p><strong>48 V drive rails</strong> (two-step, live voltage shown):</p><table tabindex="0"><thead><tr><th>Rail</th><th>Notes</th></tr></thead><tbody><tr><td><code>LEGS (48V drive)</code></td><td>Leg motor power. Can only be switched off while the robot is not standing (sitting, control off or fallen); the row is blocked otherwise.</td></tr><tr><td><code>ARM · ADDON (48V)</code></td><td>Arm and add-on power — one port for both. Confirm the arm is stopped first.</td></tr><tr><td><code>EXTERN (48V)</code></td><td>External expansion port power.</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Switching <code>LEGS (48V drive)</code> off makes the robot collapse. <code>System reboot</code> — <code>Reboot</code> → <code>Reboot the robot PC?</code> → <code>Reboot</code> — restarts the robot PC: the robot loses motor power and the app connection drops for the duration. Sit the robot on the floor before either action. The reboot dialog also has the <code>Don&#39;t ask for a day</code> checkbox.</p></div><p>Below the 48 V rails the section repeats the <code>Accelerometer calib (ACC)</code> and <code>IMU roll/pitch zero</code> rows described in <a href="/RBQ/manual/gui/settings.html#calibration">Robot settings → Calibration</a>; they behave the same here.</p><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h2><p><img src="'+n+'" alt="Vision section"></p><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Night mode (Night Vision)</code></td><td>Switches the IR-cut filter; the CCTV IR-cut and IR LED follow it (switching to day turns the IR LED off).</td></tr><tr><td><code>IR projector</code></td><td>Depth-camera dot projector, independent of night mode. Shown only on robots that have one.</td></tr><tr><td><code>Stealth mode (LED·buzzer OFF)</code></td><td>Turns the LEDs and buzzer off together.</td></tr><tr><td><code>GUIDE overlay</code></td><td>Draws the guide (Aruco cross-hair / box) on the video.</td></tr><tr><td><code>FACE DETECT</code></td><td>Draws face boxes on the video.</td></tr><tr><td><code>Dock Scan (docking marker)</code></td><td>Whether the robot detects docking markers in the camera images; the overlay and the <code>Start docking</code> button appear when one is found. While docking runs the marker is drawn whatever this says.</td></tr><tr><td><code>Video resolution (SQHD)</code></td><td>WebRTC encoder output resolution: HD 720p / SQHD 540 / <code>Eco 360</code> — lower it on a weak link.</td></tr></tbody></table><p><code>IR projector</code> and <code>Video resolution (SQHD)</code> show the state the robot reports. The other toggles show the last value sent to this robot — the app keeps it per robot, so it survives leaving the page or restarting the app, but it can differ after the robot restarts (the note at the bottom of the section says so).</p><p><code>Heightmap settings</code> — <code>Stairs</code> enables stair terrain recognition; <code>Edge</code> enables step-edge detection and is only available while <code>Stairs</code> is on.</p><p><code>Daemon control</code> — <code>VISION RESET</code> → <code>Reset</code> has the Handler restart HAL, restarting the camera pipeline cleanly. Video drops for a few seconds; the button shows <code>Resetting…</code> and stays unavailable for about 8 seconds.</p><p><code>Vision Programs</code> lets you start and stop individual vision daemons by hand (<code>Vision</code>, <code>HAL</code>, <code>Streamer</code>, <code>Handeye</code>, <code>Heightmap</code>, <code>Cctv</code>, <code>Ptz</code>, <code>Thermal</code>). Their on/off state comes from the robot&#39;s reported program status; only on older daemons that do not report it does it fall back to the last command sent.</p><h2 id="config-file" tabindex="-1">Config file <a class="header-anchor" href="#config-file" aria-label="Permalink to &quot;Config file&quot;">​</a></h2><p><img src="'+i+'" alt="Config file section"></p><p>The INI editor edits the robot daemons&#39; configuration files directly. The target selector switches between <code>Motion.ini</code>, <code>HAL · config.ini</code> and <code>Handler · config.ini</code>. Use <code>Search key</code> to filter keys; boolean values can be toggled, other values are edited in place. The header shows how many sections were read, when, and <code>Backup exists</code> if a backup file is present on the robot.</p><p>The footer counts unsaved edits (<code>{n} changes</code>). <code>Revert</code> discards them, <code>Reload</code> re-reads the file from the robot, <code>Save</code> opens the confirmation <code>Save to {label}?</code> listing every changed key with its old and new value.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Saving replaces the <strong>entire</strong> file on the robot with what the editor holds — always edit on top of a freshly loaded file. The previous file is kept as <code>*_backup.ini</code>. Changes apply only after the corresponding daemon (Motion, HAL or Handler) is restarted; the app does not restart it for you. Do not change values whose meaning you do not know.</p></div><h2 id="arm" tabindex="-1">Arm <a class="header-anchor" href="#arm" aria-label="Permalink to &quot;Arm&quot;">​</a></h2><p>Shown only when the robot reports an arm. This section is the initial bring-up.</p><ol><li>Press <code>CAN check</code>, <code>Release brake</code>, <code>Control Start</code> in that order. Wait for the status badge to light up after each step before pressing the next. ▶ Auto Start ARM runs the whole sequence in one press.</li><li><code>Static poses</code> sends a fixed pose (<code>Straight</code>, <code>Folding</code>, <code>Ready</code>, <code>Lift</code>, <code>Packing</code>, <code>DoorReady</code>) without a trajectory — on the first use start from <code>Ready</code>.</li><li><code>Joint lock / jog</code> — tap a joint card to lock or unlock it; hold <code>+</code> / <code>−</code> to jog a locked joint (the buttons are disabled while the joint is unlocked).</li></ol><p>RC01 / RC02 attachment sections are not covered by this manual.</p>',29)])])}const w=t(c,[["render",s]]);export{u as __pageData,w as default};
